DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `orderNumber` varchar(30) NOT NULL,
  `status` enum('PENDING','PREPARING','READY','COMPLETED','CANCELLED') NOT NULL DEFAULT 'PENDING',
  `type` enum('DINE_IN','TAKEOUT','DELIVERY') NOT NULL DEFAULT 'DINE_IN',
  `tableNumber` varchar(20) DEFAULT NULL,
  `customerName` varchar(100) DEFAULT NULL,
  `totalAmount` decimal(10,2) NOT NULL,
  `notes` text DEFAULT NULL,
  `branchId` int(11) NOT NULL,
  `cashierId` int(11) NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `orders_orderNumber_key` (`orderNumber`),
  KEY `orders_branchId_idx` (`branchId`),
  KEY `orders_cashierId_idx` (`cashierId`),
  KEY `orders_status_idx` (`status`),
  KEY `orders_createdAt_idx` (`createdAt`),
  CONSTRAINT `orders_branchId_fkey` FOREIGN KEY (`branchId`) REFERENCES `branches` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `orders_cashierId_fkey` FOREIGN KEY (`cashierId`) REFERENCES `users` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=38 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
